        int max = 0;
        int[] assignment = new int[n];
        generateAssignments(0, n, assignment, edges, max);
        System.out.println(max);
    }

    private static void generateAssignments(int pos, int n, int[] assignment, List<Edge> edges, int currentMax) {
        if (pos == n) {
            int count = evaluate(assignment, edges);
            if (count > currentMax) {
                currentMax = count;
            }
            return;
        }
        for (int val = 1; val <= 6; val++) {
            assignment[pos] = val;
            generateAssignments(pos + 1, n, assignment, edges, currentMax);
        }
    }

    private static int evaluate(int[] assignment, List<Edge> edges) {
        Set<String> used = new HashSet<>();
        int count = 0;
        for (Edge e : edges) {
            int u = assignment[e.a];
            int v = assignment[e.b];
            int a = Math.min(u, v);
            int b = Math.max(u, v);
            String key = a + "-" + b;
            if (!used.contains(key)) {
                used.add(key);
                count++;
            }
        }
        return count;
    }

    static class Edge {
        int a, b;
        Edge(int a, int b) {
            this.a = a;
            this.b = b;
        }
    }
}
