                try {
                    buflen = System.in.read(buffer);
                } catch (IOException e) {
                    e.printStackTrace();
                }
                if (buflen <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() {
            int c = readByte();
            while (c <= ' ') c = readByte();
            boolean neg = false;
            if (c == '-') {
                neg = true;
                c = readByte();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = readByte();
            }
            return neg ? -val : val;
        }
    }
